independent_instrumentation.spy:
extends "res://scripts/presentation/board_trial_audio.gd"
var loads:=[]
var requests:=[]
var primaries:=[]
func _load_cue(key:String,path:String)->void:
	loads.append({"key":key,"path":path})
	super._load_cue(key,path)
func play_cue(key:String,target_id:=0)->bool:
	requests.append(key)
	return super.play_cue(key,target_id)
func _play_primary(key:String)->String:
	primaries.append(key)
	return super._play_primary(key)

independent_instrumentation.controlled_subclass:
extends "/tmp/qa07-audio-silence-20261010/board.gd"
var qa_hold_brains:=false
func _brain(actor:Dictionary,delta:float)->void:
	if not qa_hold_brains:super._brain(actor,delta)

independent_instrumentation.probe:
extends SceneTree
const Config=preload("res://scripts/data/board_trial_config.gd")
const Disabled=["rat_death","boar_death","wolf_death","bear_lord_death","victory"]
var failures:=0
var cases:=[]
func _initialize():call_deferred("run")
func check(ok:bool,label:String):
	if not ok:failures+=1;push_error(label)
func fresh():
	var g=load("/tmp/qa07-audio-silence-20261010/controlled.gd").new()
	root.add_child(g);g.set_process(false)
	var s=g.audio_feedback
	check(s.loads.size()==10 and s.streams.size()==10 and s.voices.size()==16 and s.requests.is_empty(),"instrument original controller before first initializer: only ten loads and no cue requests")
	var paths:={}
	for l in s.loads:paths[l.path]=true;check(l.key not in Disabled and l.path.begins_with(s.RUNTIME),"first initializer never enters old source or forbidden key")
	check(paths.size()==9 and s.loaded_keys.size()==10 and s.streams.values().all(func(x):return x!=null),"nine genuine nonnull resources; no parent whole-set initializer")
	g.start_battle();return g
func isolate(g,ids:Array):
	for a in g.actors:
		if a.id not in ids:a.node.take_damage(a.hp_max);a.dead=true
		else:a.cooldown=100
func quiet(g,heard:Array,label:String):
	var s=g.audio_feedback
	check(s.requests.all(func(k):return k=="tangseng_hurt_warning") and s.rejected_keys.is_empty(),label+" zero natural forbidden/fallback request")
	check(heard.all(func(k):return s.FILE_BY_KEY.has(k)),label+" no forbidden/fallback scheduling")
	check(s.loads.size()==10 and s.streams.size()==10,label+" no lazy fallback load")
func mutual():
	var g=fresh();isolate(g,["tangseng","guard_monk","E7"])
	var core:Dictionary=g._record("tangseng");var monk:Dictionary=g._record("guard_monk");var bear:Dictionary=g._record("E7")
	g._set_cell(core,Vector2i(3,3));g._set_cell(bear,Vector2i(4,3));g._set_cell(monk,Vector2i(5,3))
	core.node.health=20;bear.node.health=14
	var heard:=[];g.audio_feedback.cue_played.connect(func(k):heard.append(k))
	g.combat.request(bear.node,core.node);g.combat.request(monk.node,bear.node)
	for a in [bear,monk]:a.node.presentation.pose_time=a.node.presentation.impact_delay()-Config.STEP
	g._tick(Config.STEP)
	check(core.dead and bear.dead and g.phase==g.Phase.RESULT and not g.victory and g.result_count==1,"real whole event batch kills core and final bear; failure priority settles once")
	check(heard.count("tangseng_hurt_warning")==1 and heard.count("bear_lord_attack")==1 and heard.count("guard_monk_attack")==1,"lethal valid attacks and actual core warning preserved")
	quiet(g,heard,"same tick mutual death")
	g._process(1);await process_frame;await process_frame
	check(not is_instance_valid(bear.node),"real final bear fades and frees after failure")
	g.retry();quiet(g,heard,"mutual retry")
	cases.append({"case":"core_and_last_enemy_same_tick","result":"failure","result_count":1,"heard":heard,"production_forbidden_requests":0,"actual_loads":g.audio_feedback.loads.duplicate(true)});g.free()
func splash():
	var g=fresh();g.qa_hold_brains=true;isolate(g,["tangseng","foxfire_imp","E1","E3","E5","E7"])
	g._set_cell(g._record("tangseng"),Vector2i(0,6));var fox:Dictionary=g._record("foxfire_imp");g._set_cell(fox,Vector2i(3,3))
	var ids=["E1","E3","E5","E7"];var cells=[Vector2i(5,3),Vector2i(5,2),Vector2i(5,4),Vector2i(6,3)];var bodies:=[]
	for i in 4:
		var a:Dictionary=g._record(ids[i]);g._set_cell(a,cells[i]);a.node.health=20;bodies.append(a.node)
	var heard:=[];g.audio_feedback.cue_played.connect(func(k):heard.append(k));fox.cooldown=0
	g._attack(fox,g._record("E1"))
	while g.phase==g.Phase.BATTLE and g.elapsed<2:g.step(Config.STEP)
	check(g.phase==g.Phase.RESULT and g.victory and g.result_count==1 and g.metrics.damage.get(fox.id,0)==80,"one real fox projectile kills all four enemy types and wins once")
	check(bodies.all(func(b):return b.presentation.pose=="retreat") and heard==["foxfire_imp_attack"],"four actual retreat animations, one launch primary and no death or victory substitution")
	quiet(g,heard,"four death splash")
	g._process(1);await process_frame;await process_frame
	check(bodies.all(func(b):return not is_instance_valid(b)),"all four real corpses fade and free")
	var damage:float=g.metrics.damage.get(fox.id,0)
	var freed:int=bodies.filter(func(b):return not is_instance_valid(b)).size()
	g.retry();quiet(g,heard,"four death retry")
	cases.append({"case":"four_types_one_splash","controlled_brains_held":true,"damage":damage,"primary_count":heard.count("foxfire_imp_attack"),"freed":freed,"production_forbidden_requests":0,"actual_load_count":g.audio_feedback.loads.size()});g.free()
func guards():
	var g=fresh();var s=g.audio_feedback;var heard:=[];s.cue_played.connect(func(k):heard.append(k))
	var prior:Dictionary=s.streams.duplicate()
	# Explicit illegal probes; their attempted loads/requests are NOT natural production counts.
	for key in Disabled:
		s._load_cue(key,"res://audio/candidates/v1/wav/"+key+".wav")
		check(not s.play_cue(key),"manual forbidden cue rejects "+key)
	s._load_cue("wolf_attack","res://audio/runtime/board-selected-20261009/wav/wolf_attack_full.wav")
	for key in ["ui","shared_hit_fur","failure","defeat","battle_result"]:check(not s.play_cue(key),"manual substitute key rejects "+key)
	s.hit(g._record("guard_monk").node,true,false)
	check(s.streams==prior and s.loaded_keys.size()==10 and heard.is_empty() and s.rejected_keys==Disabled,"six illegal load attempts and ten cue attempts never load or schedule fallback")
	check(is_equal_approx(s.streams.wolf_attack.get_length(),0.29),"wrong old wolf path cannot replace short stream")
	cases.append({"case":"manual_illegal_not_production","rejected_load_attempts":6,"manual_cue_requests":10,"accepted_extra_loads":0,"heard":heard});g.free()
func run():
	await mutual();await splash();guards()
	check(cases.size()==3,"three independent runtime counterexample groups complete")
	var args=OS.get_cmdline_user_args();var dest=args[0] if args.size()>0 else "/tmp/qa07-audio-silence-20261010/probe-source.json"
	var f=FileAccess.open(dest,FileAccess.WRITE);f.store_string(JSON.stringify({"actual_groups":cases.size(),"cases":cases,"failures":failures,"expected_guard_error_messages":6,"headless_only":true}))
	print("QA07_SILENCE_PROBE groups=",cases.size()," failures=",failures)
	quit(1 if failures else 0)
